    public record ClaimState(long id, long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
            String corrects, long listed, ClaimStatus status, String number, BigDecimal settledDue, boolean stated,
            BigDecimal statedDue, LocalDate deferredUntil, LocalDate remindedOn, String ref, String tags,
            boolean waived) {

        /** The claim as it stood then, unsaved. */
        public Claim rebuild(String sheetId) {
            Claim claim = new Claim(sheetId, personId, amount, date, dueBy, note, corrects, listed);
            claim.setStatus(status);
            claim.setNumber(number);
            claim.setSettledDue(settledDue);
            claim.setDeferredUntil(deferredUntil);
            claim.remind(remindedOn);
            claim.setRef(ref);
            claim.setTags(tags);
            if (waived) {
                claim.waive();
            }
            if (stated) {
                claim.bind(statedDue);
            }
            return claim;
        }
    }

    /** What the sheet holds now. */
    public static SheetState of(Sheet sheet, List<Rate> rates, List<Person> people, List<Claim> claims, Views views) {
        return new SheetState(
        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByAsOfDescIdDesc(sheetId, date)
                .map(s -> json.readValue(s.getState(), SheetState.class));
    }

    /** The line of rates as it stood at the end of a date: the sheet's own then, then each of its ancestors' as
     *  they stood then (none for one with no change made on it by then). */
    @Transactional(readOnly = true)
    public RateChain ratesAsOf(String sheetId, LocalDate date) {
        return new RateChain(Stream.concat(Stream.of(sheetId), rates.ancestorsOf(sheetId).stream())
                .map(id -> asOf(id, date).map(state -> state.rebuildRates(id)).orElse(List.<Rate>of())).toList());
    }

    /** The claim as kept: no one's editor lock is part of what the sheet held. */
    private static ClaimView unlocked(ClaimView c) {
        return new ClaimView(c.id(), c.personId(), c.amount(), c.date(), c.note(), c.status(), c.number(),
                c.settledDue(), c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(),
                c.log(), c.proofs(), c.splitFrom(), null, c.lateEntry(), c.remindedOn(), c.ref(), c.tags(),
                c.voidReason(), c.comments(), c.editedBy(), c.batch(), c.lines(), c.waived());
    }

    /** The lists the screen reads of the sheet as it stood at the end of a date; none when no change was made on it
     *  by then. */
    @Transactional(readOnly = true)
    public SheetState.Views viewsAsOf(String sheetId, LocalDate date) {
        return asOf(sheetId, date).map(SheetState::views).orElse(SheetState.Views.NONE);
    }
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * A claim as the screen shows it; the amount is given with exactly two decimals, as is the due
     * fixed when it was settled (null while it is not settled, or if its grade had no rate then); openedBy
     * is who opened it (null while a draft); stated is whether its person's last statement binds it, to
     * statedDue (null if it had no figure then, when it stays n/a); corrects is the number of the claim a correction corrects (null
     * on any other claim); deferredUntil is the day it was deferred until (null if never deferred); log is its status log, oldest first;
     * proofs is how many proofs have been given for it; splitFrom is the number of the claim it was split off (null
     * on any other claim); lockedBy is who has its editor open, locking it for other users (null when no one has);
     * lateEntry is whether it was added while its period was soft-closed; remindedOn is the last day a reminder was
     * written for it (null if never); tags are its tags, sorted (none when it has none); voidReason is the reason it
     * was voided with (null when it was voided without one, or is not void); comments are its comments, oldest
     * first; editedBy is who last edited it (null if no one has); batch is the number of the settle batch that
     * settled it (null when it was not settled by one); lines are its lines, in the order added; waived is whether
     * a steward waived its late charge.
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate dueBy, LocalDate deferredUntil, List<LogLine> log, int proofs, String splitFrom,
            String lockedBy, boolean lateEntry, LocalDate remindedOn, String ref, List<String> tags,
            String voidReason, List<CommentLine> comments, String editedBy, Integer batch, List<LineView> lines,
            boolean waived) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getBoundDue() == null ? null : claim.getBoundDue().toPlainString(), claim.getCorrects(),
                    claim.getDueBy(), claim.getDeferredUntil(), claim.getLog().stream().map(LogLine::of).toList(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
                    claim.getRemindedOn(), claim.getRef(), claim.tagList(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentLine::of).toList(), claim.getEditedBy(),
                    claim.getSettleBatch(), claim.getLines().stream().map(LineView::of).toList(),
                    claim.isWaived());
        }
    }
    }

    /** A claim's due: its settled figure, else its stated one, else its amount at the rate in force on its date of
     *  its person's grade in force on that date (the sheet's own, else its nearest ancestor's), rounded as the claim rounds (by the sheet's policy date); an overdue claim's late charge is added on top of the figure, and the
     *  sum is raised to the floor in force on its date unless it is a correction. */
    private static BigDecimal dueOf(Claim claim, String grade, RateChain sheetRates, Sheet sheet, List<Claim> sheetClaims) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
                : sheetRates.inForceOn(grade, claim.getDate(), claim.getId())
                        .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), rounding))
                        .orElse(null);
        return figure == null || sheet == null ? figure
                : ClaimService.floored(claim, figure.add(ClaimService.lateCharge(claim, figure, sheet, grade)), sheet);
    }
}
